    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(length, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < length:
            result.append((start, length))
        return result

    rb = bands(h, row_seps)
    cb = bands(w, col_seps)
    row_index = {r: i for i, (a, b) in enumerate(rb) for r in range(a, b)}
    col_index = {c: i for i, (a, b) in enumerate(cb) for c in range(a, b)}

    points = {2: set(), 3: set()}
    for r in range(h):
        for c in range(w):
            if grid[r][c] in points:
                points[grid[r][c]].add((row_index[r], col_index[c]))

    coverage = {2: set(), 3: set()}
    for color, pts in points.items():
        pts = list(pts)
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        coverage[color].add((r1, c))
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        coverage[color].add((r, c1))

    out = [row[:] for row in grid]
    for ri in range(len(rb)):
        for ci in range(len(cb)):
            has2 = (ri, ci) in coverage[2]
            has3 = (ri, ci) in coverage[3]
            if not (has2 or has3):
                continue
            color = 6 if has2 and has3 else (2 if has2 else 3)
            ra, rz = rb[ri]
            ca, cz = cb[ci]
            for r in range(ra, rz):
                for c in range(ca, cz):
                    out[r][c] = color
    return out
